static float lm_dot2(lm_vec2 a, lm_vec2 b) {
    return a.x * b.x + a.y * b.y;
}

lm_vec2 to_barycentric(lm_vec2 p1, lm_vec2 p2, lm_vec2 p3, lm_vec2 p) {
    lm_vec2 v0 = lm_sub2(p3, p1);
    lm_vec2 v1 = lm_sub2(p2, p1);
    lm_vec2 v2 = lm_sub2(p, p1);
